# ヴィジョンはジャーヴィスと同じ俳優（ポール・ベタニー）
IMAGES["timely"] = IMAGES["remains"]  # 同じ俳優（ジョナサン・メジャース）
IMAGES["captain-marvel:monica"] = None  # 子ども時代のモニカは子役なので写真なし
IMAGES["kang"] = IMAGES["remains"]  # 同じ俳優（ジョナサン・メジャース）
IMAGES["marc"] = IMAGES["steven"] = IMAGES["apocalypse"]  # オスカー・アイザック（ムーンナイト）
IMAGES["logan:laura"] = None  # 『LOGAN』のローラは子役
IMAGES["sprite"] = None  # 子役
IMAGES["vision"] = IMAGES["jarvis"]


def image_for(slug, pid):
    """その作品のその人物の顔写真。作品ごとに俳優が違う人物（ハワード・スタークなど）は "作品のslug:人物id" で登録する"""
    key = f"{slug}:{pid}"
    if key in IMAGES:  # None を入れると、その作品では写真なし（頭文字のアイコン）にできる
        return IMAGES[key]
    return IMAGES.get(pid)
